from pymongo import MongoClient
client = MongoClient()
coll = client.db.test
coll.insert_one({'data': [1, 2, 3, 4, 5]})
pipeline = [
    {'$project': {
        'filtered': {
            '$filter': {
                'input': '$data',
                'as': 'num',
                'cond': {'$gt': ['$$num', 2]}
            }
        }
    }}
]
result = list(coll.aggregate(pipeline))
print(result[0]['filtered'])

