from pymongo import MongoClient
client = MongoClient()
coll = client.db.test
coll.insert_one({'meta': {'tags': ['python', 'mongodb', 'redis', 'python', 'flask']}})
pipeline = [
    {'$project': {
        'distinct_tags': {
            '$reduce': {
                'input': '$meta.tags',
                'initialValue': [],
                'in': {
                    '$cond': {
                        'if': {'$in': ['$$this', '$$value']},
                        'then': '$$value',
                        'else': {'$concatArrays': ['$$value', ['$$this']]}
                    }
                }
            }
        }
    }}
]
result = list(coll.aggregate(pipeline))
print(sorted(result[0]['distinct_tags']))

